using System;using System.Data;using System.Text;using System.Web;using System.Web.UI;using HospitalMSWebApp.Infrastructure;using HospitalMSWebApp.Services;
namespace HospitalMSWebApp.Views.Pharmacist{public class Workspace:AppPage{readonly Database db=new Database();readonly HospitalWorkflowService wf=new HospitalWorkflowService();string csrf;protected void Page_Load(object s,EventArgs e){if(!RequireRoles("Pharmacist"))return;csrf=Convert.ToString(Session["PharmCsrf"]);if(string.IsNullOrEmpty(csrf)){csrf=Guid.NewGuid().ToString("N");Session["PharmCsrf"]=csrf;}if(Request.HttpMethod=="POST")Post();}void Post(){if(Request.Form["csrf"]!=csrf){Go("Security validation failed.",true);return;}try{Session["PharmCsrf"]=Guid.NewGuid().ToString("N");if(V("action")=="dispense"){var q=D("quantity");if(q<=0)throw new ArgumentException("Enter a positive quantity.");wf.DispensePrescriptionItem(L("itemId"),L("batchId"),q,CurrentUser.UserId);AuditService.Write(CurrentUser,"PrescriptionDispensed","PrescriptionItem",V("itemId"),"Medication dispensed from pharmacist workspace",Request);Go("Dispensing recorded and patient notified.",false);}else if(V("action")=="stock"){wf.ReceiveStock(I("medicationId"),Req("batch"),Date("expires"),D("quantity"),D0("minimum"),D0("cost"),IN("supplierId"));AuditService.Write(CurrentUser,"StockReceived","MedicationBatch",null,"Stock received in pharmacist workspace",Request);Go("Stock batch received.",false);}else throw new ArgumentException("Unsupported action.");}catch(Exception x){Go(x is ArgumentException||x is InvalidOperationException?x.Message:"Pharmacy action failed.",true);}}protected override void Render(HtmlTextWriter w){ if(Response.IsRequestBeingRedirected || CurrentUser==null)return;var b=new StringBuilder(GuardianUi.Begin(CurrentUser,"Pharmacy workspace",Request.Path));N(b);b.Append("<div class='row'>").Append(GuardianUi.Stat("Prescriptions waiting",db.Scalar("SELECT COUNT(*) FROM gh.PrescriptionOrders WHERE Status IN('Pending','PartiallyDispensed')"))).Append(GuardianUi.Stat("Low-stock batches",db.Scalar("SELECT COUNT(*) FROM gh.MedicationBatches WHERE QuantityOnHand<=MinimumStock"))).Append(GuardianUi.Stat("Expiring in 30 days",db.Scalar("SELECT COUNT(*) FROM gh.MedicationBatches WHERE ExpirationDate BETWEEN CAST(SYSUTCDATETIME() AS date) AND DATEADD(day,30,CAST(SYSUTCDATETIME() AS date)) AND QuantityOnHand>0"))).Append(GuardianUi.Stat("Dispensations today",db.Scalar("SELECT COUNT(*) FROM gh.Dispensations WHERE CAST(DispensedAt AS date)=CAST(SYSUTCDATETIME() AS date)"))).Append("</div>");b.Append("<section class='panel'><h2>Prescription dispensing queue</h2>").Append(GuardianUi.Table(db.Query(@"SELECT TOP 100 pi.PrescriptionItemId AS [Item],p.MedicalRecordNumber AS [MRN],p.patientName AS [Patient],m.MedicationName AS [Medication],pi.Dose,pi.Frequency,pi.Quantity-ISNULL(SUM(d.Quantity),0) AS [Remaining],po.Status FROM gh.PrescriptionItems pi JOIN gh.PrescriptionOrders po ON po.PrescriptionOrderId=pi.PrescriptionOrderId JOIN dbo.patientTbl p ON p.patientId=po.PatientId JOIN gh.MedicationCatalog m ON m.MedicationId=pi.MedicationId LEFT JOIN gh.Dispensations d ON d.PrescriptionItemId=pi.PrescriptionItemId WHERE po.Status IN('Pending','PartiallyDispensed') GROUP BY pi.PrescriptionItemId,p.MedicalRecordNumber,p.patientName,m.MedicationName,pi.Dose,pi.Frequency,pi.Quantity,po.Status HAVING pi.Quantity-ISNULL(SUM(d.Quantity),0)>0"),"Item","Workspace.aspx?itemId=","Review prescription","#dispense-prescription")).Append("</section><section class='panel'><h2>Inventory and alerts</h2>").Append(T(db.Query(@"SELECT m.MedicationName AS [Medication],b.MedicationBatchId AS [Batch ID],b.BatchNumber AS [Batch],CONVERT(varchar(10),b.ExpirationDate,23) AS [Expires],b.QuantityOnHand AS [On hand],b.MinimumStock AS [Minimum],CASE WHEN b.ExpirationDate<CAST(SYSUTCDATETIME() AS date) THEN 'Expired' WHEN b.QuantityOnHand<=b.MinimumStock THEN 'Low stock' WHEN b.ExpirationDate<DATEADD(day,30,CAST(SYSUTCDATETIME() AS date)) THEN 'Near expiry' ELSE 'In stock' END AS [Alert],s.SupplierName AS [Supplier] FROM gh.MedicationBatches b JOIN gh.MedicationCatalog m ON m.MedicationId=b.MedicationId LEFT JOIN gh.Suppliers s ON s.SupplierId=b.SupplierId ORDER BY b.ExpirationDate"))).Append("</section><section class='split'><div class='panel compact'><h2>Dispense prescription</h2>").Append(F("dispense")).Append("</div><div class='panel compact'><h2>Receive stock</h2>").Append(F("stock")).Append("</div></section><section class='panel'><h2>Stock movement history</h2>").Append(T(db.Query("SELECT TOP 100 m.MedicationName AS [Medication],b.BatchNumber AS [Batch],x.MovementType AS [Movement],x.Quantity, x.ReferenceType AS [Reference],CONVERT(varchar(16),x.RecordedAt,120) AS [Recorded] FROM gh.StockMovements x JOIN gh.MedicationBatches b ON b.MedicationBatchId=x.MedicationBatchId JOIN gh.MedicationCatalog m ON m.MedicationId=b.MedicationId ORDER BY x.RecordedAt DESC"))).Append("</section>").Append(GuardianUi.End());w.Write(b.ToString());}string F(string a){if(a=="dispense")return DispensingTask();return "<form method='post' class='form-grid'><input type='hidden' name='csrf' value='"+H(csrf)+"'><input type='hidden' name='action' value='stock'>"+O("Medication","medicationId","SELECT MedicationId AS Id,MedicationName AS Name FROM gh.MedicationCatalog WHERE IsActive=1",true)+O("Supplier","supplierId","SELECT SupplierId AS Id,SupplierName AS Name FROM gh.Suppliers WHERE IsActive=1",false)+In("Batch","batch","text",true)+In("Expires","expires","date",true)+In("Quantity","quantity","number",true)+In("Minimum","minimum","number",false)+In("Unit cost","cost","number",false)+"<button>Receive stock</button></form>";}
string DispensingTask(){
 string picker="<form method='get' action='#dispense-prescription' class='form-grid'>"+O("Prescription","itemId","SELECT i.PrescriptionItemId AS Id,p.MedicalRecordNumber+' · '+p.patientName+' — '+m.MedicationName AS Name FROM gh.PrescriptionItems i JOIN gh.PrescriptionOrders o ON o.PrescriptionOrderId=i.PrescriptionOrderId JOIN dbo.patientTbl p ON p.patientId=o.PatientId JOIN gh.MedicationCatalog m ON m.MedicationId=i.MedicationId WHERE o.Status IN('Pending','PartiallyDispensed') AND i.Quantity>ISNULL((SELECT SUM(Quantity) FROM gh.Dispensations WHERE PrescriptionItemId=i.PrescriptionItemId),0)",true)+"<button>Open prescription</button></form>";
 long item;if(!long.TryParse(Request.QueryString["itemId"],out item)||item<1)return picker+"<p>Open a prescription to see its patient, remaining quantity and matching batches.</p>";
 var selected=db.Query(@"SELECT i.PrescriptionItemId,i.MedicationId,p.patientName,p.MedicalRecordNumber,p.patientAllergies,m.MedicationName,i.Dose,i.Frequency,
 i.Quantity-ISNULL((SELECT SUM(Quantity) FROM gh.Dispensations WHERE PrescriptionItemId=i.PrescriptionItemId),0) AS Remaining
 FROM gh.PrescriptionItems i JOIN gh.PrescriptionOrders o ON o.PrescriptionOrderId=i.PrescriptionOrderId
 JOIN dbo.patientTbl p ON p.patientId=o.PatientId JOIN gh.MedicationCatalog m ON m.MedicationId=i.MedicationId
 WHERE i.PrescriptionItemId=@I AND o.Status IN('Pending','PartiallyDispensed')",Database.Parameter("@I",item));
 if(selected.Rows.Count!=1||Convert.ToDecimal(selected.Rows[0]["Remaining"])<=0)return picker+"<p role='status'>This prescription is no longer awaiting dispensing. Refresh the queue.</p>";
 var row=selected.Rows[0];string allergy=Convert.ToString(row["patientAllergies"]);
 string context="<section aria-label='Dispensing patient context'><p><strong>"+H(Convert.ToString(row["patientName"]))+" · "+H(Convert.ToString(row["MedicalRecordNumber"]))+"</strong></p><p><strong>Recorded allergies:</strong> "+H(string.IsNullOrWhiteSpace(allergy)?"Not recorded — confirm before dispensing":allergy)+"</p><p>"+H(Convert.ToString(row["MedicationName"]))+" · "+H(Convert.ToString(row["Dose"]))+" · "+H(Convert.ToString(row["Frequency"]))+"</p><p>Remaining prescribed quantity: "+H(Convert.ToString(row["Remaining"],System.Globalization.CultureInfo.InvariantCulture))+"</p></section>";
 var batches=db.Query("SELECT MedicationBatchId,BatchNumber,ExpirationDate,QuantityOnHand,MinimumStock FROM gh.MedicationBatches WHERE MedicationId=@M AND QuantityOnHand>0 AND ExpirationDate>=CAST(SYSUTCDATETIME() AS date) ORDER BY ExpirationDate,MedicationBatchId",Database.Parameter("@M",row["MedicationId"]));
 if(batches.Rows.Count==0)return picker+context+"<p>No matching in-date stock is available. <a href='Suppliers.aspx'>Review supplier deliveries and reconciliation</a>. No dispensing can be recorded.</p>";
 var options=new StringBuilder("<label>Matching medication batch<select name='batchId' required><option value=''>Choose a batch…</option>");
 foreach(DataRow batch in batches.Rows)options.Append("<option value='").Append(batch["MedicationBatchId"]).Append("'>").Append(H(Convert.ToString(batch["BatchNumber"])+" · expires "+Convert.ToDateTime(batch["ExpirationDate"]).ToString("yyyy-MM-dd")+" · on hand "+Convert.ToString(batch["QuantityOnHand"],System.Globalization.CultureInfo.InvariantCulture))).Append("</option>");
 options.Append("</select></label>");
 return picker+context+"<p>Matching, in-date batches are ordered by expiry. Recheck the physical pack before dispensing; stock and remaining quantity are validated again on submission.</p><form method='post' class='form-grid'><input type='hidden' name='csrf' value='"+H(csrf)+"'><input type='hidden' name='action' value='dispense'><input type='hidden' name='itemId' value='"+item+"'>"+options+In("Quantity","quantity","number",true)+"<button>Dispense</button></form>";
}
string O(string l,string n,string q,bool r){var t=db.Query(q);var b=new StringBuilder("<label>"+l+"<select name='"+n+"'"+(r?" required":"")+"><option value=''>Select</option>");foreach(DataRow x in t.Rows)b.Append("<option value='").Append(H(Convert.ToString(x["Id"]))).Append(n=="itemId"&&Convert.ToString(x["Id"])==Request.QueryString["itemId"]?"' selected>":"'>").Append(H(Convert.ToString(x["Name"]))).Append("</option>");return b.Append("</select></label>").ToString();}static string In(string l,string n,string t,bool r){return "<label>"+l+"<input name='"+n+"' type='"+t+"'"+(r?" required":"")+(t=="number"?" step='any' min='0'":"")+"></label>";}static string H(string s){return HttpUtility.HtmlEncode(s??"");}static string T(DataTable t){return GuardianUi.Table(t);}string V(string k){return(Request.Form[k]??"").Trim();}string Req(string k){var v=V(k);if(string.IsNullOrEmpty(v))throw new ArgumentException("Enter "+k+".");return v;}int I(string k){return IN(k).GetValueOrDefault();}int? IN(string k){int x;if(V(k)=="")return null;if(!int.TryParse(V(k),out x))throw new ArgumentException("Enter a valid "+k+".");return x;}long L(string k){long x;if(!long.TryParse(V(k),out x)||x<1)throw new ArgumentException("Select a valid record.");return x;}decimal D(string k){decimal x;if(!decimal.TryParse(V(k),out x)||x<=0)throw new ArgumentException("Enter a positive quantity.");return x;}decimal D0(string k){decimal x;if(V(k)=="")return 0;if(!decimal.TryParse(V(k),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out x)||x<0)throw new ArgumentException("Enter a valid non-negative "+k+".");return x;}DateTime Date(string k){DateTime x;if(!DateTime.TryParse(V(k),out x))throw new ArgumentException("Enter an expiration date.");return x;}void N(StringBuilder b){var n=Request.QueryString["notice"];var e=Request.QueryString["error"];if(n!=null)b.Append("<div class='notice success'>✓ ").Append(H(n)).Append("</div>");if(e!=null)b.Append("<div class='notice error'>! ").Append(H(e)).Append("</div>");}void Go(string m,bool e){long selected;long.TryParse(Request.Form["itemId"],out selected);Response.Redirect("Workspace.aspx?itemId="+selected+"&"+(e?"error":"notice")+"="+HttpUtility.UrlEncode(m)+(selected>0?"#dispense-prescription":"#receive-stock"),false);Context.ApplicationInstance.CompleteRequest();}}}
